export function makeGuides(t){const timing={journey:journeyTiming,breath:{end:174,breathAt:32,breathUntil:152,at:[0,9,19,32,65,152],hold:[6,8,11,6,7,8]},body:{end:87,at:[0,17,35,53,72],hold:[8,8,8,8,7]},senses:{end:85,at:[0,20,40,63],hold:[9,8,9,8]}};return Object.fromEntries(Object.entries(timing).map(([key,g])=>[key,{...g,name:t[key+'Name'],about:t.guides[key].about,cues:g.at.map((at,i)=>({at,hold:g.hold[i],text:t.guides[key].cues[i]}))}]));}
export function applyCopy(lang,t=copy[lang]){document.documentElement.lang=lang;document.title=t.title;document.querySelector('meta[name=description]').content=t.description;for(const el of document.querySelectorAll('[data-i18n]'))el.textContent=t[el.dataset.i18n];for(const el of document.querySelectorAll('[data-i18n-aria]'))el.setAttribute('aria-label',t[el.dataset.i18nAria]);for(const el of document.querySelectorAll('[data-language]'))el.setAttribute('aria-pressed',String(el.dataset.language===lang));}
